wp:postmeta.wp:meta_value:
a:3:{s:7:"widgets";a:1:{i:0;a:9:{s:5:"title";s:0:"";s:4:"text";s:1301:"<div class="recross-vision-wrap">
<div class="recross-vision-cards">
<section class="recross-vision-card">
<h3 class="recross-vision-title">企業理念</h3>
<div class="recross-vision-line" aria-hidden="true"></div>
<p class="recross-vision-text">株式会社リクロスは
Re（再び）'cross（交わる）を元に
すべての縁に愛・感謝の心をもって
社会に貢献する</p>

</section>
<section class="recross-vision-card">
<h3 class="recross-vision-title">VISION</h3>
<div class="recross-vision-line" aria-hidden="true"></div>
<p class="recross-vision-text">信頼ある経営、
常に学び成長し、
企業ブランディングの
日本一のサポーターとなる。</p>

</section>
<section class="recross-vision-card">
<h3 class="recross-vision-title">MISSION</h3>
<div class="recross-vision-line" aria-hidden="true"></div>
<p class="recross-vision-text">業界のリーダーシップを取り、
社会・企業により良い変化を生み出す。</p>

</section>
<section class="recross-vision-card">
<h3 class="recross-vision-title">VALUE</h3>
<div class="recross-vision-line" aria-hidden="true"></div>
<p class="recross-vision-text">様々な技術・知識をもって、
お客様によりよいサービスを提供します。</p>

</section></div>
</div>";s:20:"text_selected_editor";s:4:"html";s:5:"autop";b:1;s:12:"_sow_form_id";s:31:"9775258706997f437be2cc709517292";s:19:"_sow_form_timestamp";d:1772459858698;s:11:"panels_info";a:6:{s:5:"class";s:31:"SiteOrigin_Widget_Editor_Widget";s:4:"grid";i:0;s:4:"cell";i:0;s:2:"id";i:0;s:9:"widget_id";s:36:"583b1071-931c-4f36-8210-44053943bb26";s:5:"style";a:6:{s:10:"widget_css";s:1193:"  .recross-vision-wrap{
    width: min(820px, 100%);
    margin: 0 auto;
    padding: 10px 8px 24px;
  }

  .recross-vision-cards{
    display: flex;
    flex-direction: column;
    gap: 26px;
  }

  .recross-vision-card{
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,.08); /* ぼかし10 / #000 8% */
    border: 1px solid rgba(0,0,0,.04);
    padding: 16px 22px 26px;
  }

  .recross-vision-title{
    margin: 0 0 10px;
    text-align: center;
    font-weight: 700;
    font-size: 16px;
    letter-spacing: .06em;
    color: #111;
  }

  .recross-vision-line{
    height: 1px;
    background: #e60012;
    margin: 0 -22px 18px; /* 線をカードの端まで伸ばす */
  }

  .recross-vision-text{
    margin: 0;
    text-align: center;
    font-size: 13px;
    line-height: 1.95;
    font-weight: 600;
    color: #111;
    word-break: break-word;
  }

  /* SP微調整 */
  @media (max-width: 768px){
    .recross-vision-wrap{ padding: 8px 6px 18px; }
    .recross-vision-card{ padding: 14px 16px 22px; }
    .recross-vision-line{ margin: 0 -16px 16px; }
    .recross-vision-title{ font-size: 15px; }
    .recross-vision-text{ font-size: 12.5px; }
  }
