[{"id":"8da64e9","elType":"container","settings":{"flex_direction":"column","html_tag":"a","css_classes":"service-top","custom_css":"/* 親コンテナ（画像＋タイトルの部分） */
.service-top {
 position: relative;
 overflow: hidden;
 transition: transform 0.3s ease-in-out;
}

/* 画像コンテナ（4:3の比率に固定） */
.service-top-img {
 position: relative;
 width: 100%;
 height: 0;
 padding-top: 75%; /* 4:3の比率 */
 overflow: hidden;
}

/* 画像のスタイル */
.service-top-img img {
 position: absolute;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 object-fit: cover; /* 画像をカバー表示 */
 transition: transform 0.3s ease-in-out;
 display: block;
}

/* タイトル部分（グレーの背景） */
.service-top-title {
 background: #666; /* タイトルの背景色 */
 color: #fff; /* タイトルの文字色 */
 text-align: center;
 padding: 10px;
 font-size: 16px;
 transition: background 0.3s ease-in-out;
}

/* ホバー時の画像の拡大 */
.service-top:hover .service-top-img img {
 transform: scale(1.1);
}

/* ホバー時に白っぽいオーバーレイを追加 */
.service-top::after {
 content: "";
 position: absolute;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 background: rgba(255, 255, 255, 0.2); /* 10% 白のオーバーレイ */
 mix-blend-mode: lighten; /* 白さを強調する */
 opacity: 0; /* 初期状態は透明 */
 transition: opacity 0.3s ease-in-out;
 pointer-events: none; /* クリックを邪魔しない */
}

/* ホバー時に白っぽくする */
.service-top:hover::after {
 opacity: 1; /* ホバー時に白が上に乗る */
}","__dynamic__":{"link":"[elementor-tag id="191e1ea" name="post-url" settings="%7B%7D"]"}},"elements":[{"id":"97e85ab","elType":"container","settings":{"content_width":"full"},"elements":[{"id":"85b2d06","elType":"widget","settings":{"_css_classes":"service-top-img","__dynamic__":{"image":"[elementor-tag id="892c05f" name="post-featured-image" settings="%7B%7D"]"}},"elements":[],"widgetType":"image"}],"isInner":true},{"id":"d03ee7c","elType":"container","settings":{"content_width":"full","flex_align_items":"center","background_background":"classic","padding":{"unit":"px","top":"10","right":"0","bottom":"10","left":"0","isLinked":false},"__globals__":{"background_color":"globals/colors?id=primary"}},"elements":[{"id":"eaa7dbc","elType":"widget","settings":{"title":"ここに見出しテキストを追加","title_color":"#FFFFFF","__dynamic__":{"title":"[elementor-tag id="b4a655a" name="post-title" settings="%7B%7D"]"}},"elements":[],"widgetType":"heading"}],"isInner":true}],"isInner":false}]

