item.content:encoded:
.recross-vision-wrap{
    width: min(820px, 100%);
    margin: 0 auto;

  }

  .recross-vision-cards{
    display: flex;
    flex-direction: column;
    gap: 26px;
  }

  .recross-vision-card{
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,.08);
    border: 1px solid rgba(0,0,0,.04);
    overflow: hidden;
    padding: 0 22px 26px;
  }

  .recross-vision-title{
    margin: 0 -22px 0px;
    padding: 14px 22px 12px;
    text-align: center;
    font-weight: 700;
    font-size: 16px;
    letter-spacing: .06em;
    color: #111;
    background: linear-gradient(360deg, #F5F5F5 0%, #E9E9E9 100%); 
  }

  .recross-vision-line{
    height: 1px;
    background: #e60012;
    margin: 0 -22px 18px;
  }

  .recross-vision-text{
    margin: 0;
    text-align: center;
    font-size: 13px;
    line-height: 1.95;
    font-weight: 600;
    color: #111;
    word-break: break-word;
  }

  @media (max-width: 750px){
    .recross-vision-wrap{ padding: 8px 6px 18px; }
    .recross-vision-card{ padding: 0 16px 22px; }
    .recross-vision-title{
      margin: 0 -16px 10px;
      padding: 13px 16px 11px;
      font-size: 15px;
    }
    .recross-vision-line{ margin: 0 -16px 16px; }
    .recross-vision-text{ font-size: 12.5px; }
		.recross-topmv__dots{
			margin-bottom:10px;
		}
  }

/* 右：バナー（PC/TAB） */
.recross-topmv__banner{
  width:100%;
  max-width:435px;
  aspect-ratio:435 / 135;
  overflow:hidden;
  background:#f1f1f1;
  margin:0 0 14px auto;
  box-sizing:border-box;
}
.recross-topmv__banner a{
  display:block;
  width:100%;
  height:100%;
}
.recross-topmv__banner img{
  display:block;
  width:100%;
  height:100%;
  max-width:none;
  object-fit:cover;
}

/* 1200px以下は縦並び（TAB/SP） */
@media (max-width:1200px){
  .recross-topmv__inner{ padding:0 14px; }
  .recross-topmv__grid{ display:block; }

  .recross-topmv__left,
  .recross-topmv__slider,
  .recross-topmv__dots{
    width:100%;
    max-width:100%;
  }
  .recross-topmv__dots{ margin-bottom:14px; }

  .recross-topmv__banner{
    width:100%;
    max-width:350px;
    margin:0 auto 14px;
  }

  .recross-topmv__newshead{
    padding-left:28px;
  }
  .recross-topmv__newshead::before{
    width:10px;
  }
}

/* SPだけ：バナーを画面幅内に収める */
@media (max-width:750px){
  .recross-topmv__banner{
    width:100%;
    max-width:100%;
    margin:0 0 14px;
  }

  .recross-topmv__banner a{
    width:100%;
    height:100%;
  }

  .recross-topmv__banner img{
    width:100%;
    height:100%;
    max-width:100%;
    object-fit:cover;
  }
	.recross-topmv__right{
		margin-top:10px;
	}
}

