.rsvp-form {
  --gap: 50px;
  --badge-bg: #f2c6c6;         /* 見た目はお好みで */
  --badge-color: #b50000;
  --border: 1px solid rgba(0,0,0,.08);
  font-size: 16px;
}

/* 3カラム → SPで1カラム */
.rsvp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: var(--gap);
  margin-bottom: 24px;
}

.rsvp-block {
    width: 100%;
    text-align: center;
}

.rsvp-block .wpcf7-radio .first,
.rsvp-block .wpcf7-radio .last,
.rsvp-block .wpcf7-checkbox {
    width: 100%;
    font-size: 24px;
}


.badge {
  display: inline-block;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  padding: 4px 8px;
  margin-left: 5px;
  border-radius: 14px;
  background: #D56A6A;
  color: #FFF;
}

.wpcf7-form-control-wrap input,
.wpcf7-form-control-wrap textarea {
  margin-top: 10px;
  margin-bottom: 10px;
}

.wpcf7-spinner {
    display: none;
}

.wpcf7-not-valid-tip {
    margin-top: -8px;
}

@media (max-width: 750px) {
  .rsvp-grid {
    grid-template-columns: 1fr;
  }
}

/* カード風ブロック（1カラム目の枠） */
.rsvp-block {
  border: initial;
  padding: 16px;
  border-radius: 6px;
}
.rsvp-legend {
  font-weight: 700;
  margin-bottom: 8px;
}

/* 見出しと「※必須」バッジ */
.rsvp-label, .rsvp-legend {
  display: block;
  font-weight: 700;
  margin: 0 0 6px;
}

/* フィールド余白 */
.rsvp-field { margin-bottom: 16px; }

/* テキスト・テキストエリア等の共通スタイル（テーマに合わせて） */
.rsvp-form input[type="text"],
.rsvp-form input[type="email"],
.rsvp-form input[type="tel"],
.rsvp-form textarea {
  width: 100%;
  box-sizing: border-box;
  padding: 10px 12px;
  border: 1px solid #ddd;
  border-radius: 4px;
  background: #fff;
}

/* CF7のラジオ/チェックのラベル折返し調整 */
.wpcf7-list-item { margin: 0 1em .5em 0; }

/* 説明文 */
.rsvp-note {
  font-size: 13px;
  line-height: 1.7;
  margin: 10px 0 0;
  color: #555;
}

/* 送信ボタン（常に1カラム最下部） */
.rsvp-actions {
  margin-top: 8px;
  text-align: center;
}
.rsvp-submit {
  background: #5AABBA;
  color: #FFF;
  display: inline-block;
  width: min(100%, 360px);
  padding: 14px 18px;
  border: none;
  border-radius: 999px;
  font-weight: 700;
  cursor: pointer;
}
.rsvp-submit:hover {
  background: #709CA4;
}

/* CF7バリデーション表示の微調整（任意） */
.wpcf7-not-valid-tip {
  margin-top: 6px;
  font-size: 12px;
}
.wpcf7-response-output {
  margin: 16px 0 0;
}"},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"2eedd5e","elType":"container","settings":{"content_width":"full","margin":{"unit":"px","top":"50","right":"0","bottom":"50","left":"0","isLinked":false}},"elements":[{"id":"c7ff2e5","elType":"widget","settings":{"title":"ⒸINVY powerd by Re’cross","header_size":"p","align":"center","typography_typography":"custom","typography_font_family":"M PLUS 1","typography_font_size":{"unit":"px","size":11,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":14,"sizes":[]},"typography_font_weight":"600","title_color":"#8F8F8F"},"elements":[],"widgetType":"heading"}],"isInner":true}],"isInner":false}]

