.sp-menu-content {
 display: none;
 position: fixed;
 top: 0;
 left: 0;
 width: 100%;
 height: 90%;
 z-index: 1001;
 overflow-y: auto;
 padding: 0px;
 font-family: 'M PLUS 1p', sans-serif; /* フォントをM PLUS 1pに設定 */
}

/* 表示時のアニメーション */
.sp-menu-content.show {
 display: flex;
 flex-direction: column; /* カラムレイアウト */
 animation: spSlideDown 0.7s ease; /* スライドインアニメーション */
}

/* 各カラムのスタイル */
.sp-menu-column {
 flex: 1;
 padding: 15px;
}

/* カラム1の背景色 */
.sp-menu-column.column-1 {
 background-color: #6DADA5; /* カラム1の背景色 */
 padding-bottom:0px;
}

/* カラム2の背景色 */
.sp-menu-column.column-2 {
 background-color: #5E958E; /* カラム2の背景色 */
 padding-top: 0px;
}

/* クローズボタン */
.sp-close-button {
 position: absolute;
 top: 10px;
 right: 20px;
 background: none;
 border: none;
 font-size: 24px;
 color: #FFFFFF;
 cursor: pointer;
 z-index: 1100;
 outline: none;
}

/* トグルボタン */
.sp-icon-style {
 font-size: 32px;
 font-weight: bold;
 color: #6DADA5;
 border: none;
 background: none;
 cursor: pointer;
}

/* メニューリスト全体 */
.sp-menu {
 list-style: none;
 padding: 0;
 margin: 0;
}

/* 各メニューアイテムのスタイル */
.sp-menu > li {
 font-size: 14px;
 font-weight: bold;
 color: #FFFFFF;
 border-bottom: 1px solid #84BBB4;
 padding:10px 0;
}

/* 子メニュー、孫メニュー */
.sub-menu,
.region-menu,
.sub-region-menu {
 list-style: none;
 margin: 0;
 padding: 10px 15px; /* インデント */
 display: none; /* 初期状態で非表示 */
}

/* 子メニュー、孫メニュー表示時 */
.sp-menu .menu-item.open > .sub-menu,
.sp-menu .region.open > .sub-region-menu {
 display: block;
 animation: spFadeIn 0.5s ease; /* フェードインアニメーション */
}

/* トグルアイコンのスタイル */
.toggle-icon {
 float: right;
 font-size: 14px;
 font-weight: bold;
 color: #FFFFFF;
 cursor: pointer;
}

/* リンクスタイル */
.sp-menu a {
 color: #DDDDDD;
 text-decoration: none;
 font-size: 14px;
 font-weight: bold;
}


/* アニメーション */
@keyframes spSlideDown {
 from {
 transform: translateY(-100%);
 opacity: 0;
 }
 to {
 transform: translateY(0);
 opacity: 1;
 }
}

@keyframes spFadeIn {
 from {
 opacity: 0;
 transform: translateY(-10px);
 }
 to {
 opacity: 1;
 transform: translateY(0);
 }
}

/* オーバーレイ（背景のぼかし部分） */
.sp-overlay {
 display: none;
 position: fixed;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 background: rgba(0, 0, 0, 0.6);
 backdrop-filter: blur(5px); /* ブラー処理 */
 z-index: 1000;
}

/* オーバーレイ表示時 */
.sp-overlay.show {
 display: block;
}

/* トグルボタンのhover効果を削除 */
.sp-icon-style:hover,
.sp-close-button:hover,
.toggle-icon:hover {
 background: none; /* 背景色の変更を無効化 */
 color: inherit; /* 色の変更も無効化（必要に応じて削除） */
 cursor: pointer; /* ポインタはそのまま維持 */
}

/* メニューリンクのhover効果を削除 */
.sp-menu a:hover {
 background: none; /* 背景色の変更を無効化 */
 color: inherit; /* テキスト色の変更も無効化 */
 text-decoration: none; /* 下線などの効果を無効化 */
}

.sp-menu > li:last-child {
 border-bottom: none; /* 最後のアイテムのボーダーを削除 */
}

.region-menu > li {
 border-bottom: 1px solid #84BBB4;
}

.region-menu{
 padding:0px;
}

.region{
 padding-left:10px;
 padding-top:10px;
 padding-bottom:10px;
}

.menu-item{
 padding-left: 10px;
 padding-right: 10px;
}

.sp-menu-column {
 padding-left: 0px;
 padding-right: 0px;
}

.sp-menu a{
 padding-left: 10px;
}

.toggle-icon{
 padding-right:10px;
 padding-left: 30px;
}

.sp-close-button{
 padding-top: 0px;
}
